      "resourceType": "Observation",
      "id": "observation-7",
      "status": "final",
      "code": {
        "text": "Skin tenderness and pain"
      },
      "subject": {
        "reference": "Patient/patient-1"
      },
      "valueString": "Reports burning, stinging skin tenderness, especially on the torso under the bra line; pain rated 6/10 when clothes rub. Marked tenderness to light touch on examination; patient said it stings a lot when touched."
