    },
    {
      "resourceType": "Observation",
      "id": "observation-10",
      "status": "final",
      "code": {
        "text": "Initial systemic symptoms"
      },
      "subject": {
        "reference": "Patient/patient-1"
      },
      "valueString": "At onset approximately 3 days ago, felt flu-like at work, with mild headache, fatigue, and low-grade fever."
    },
    {
      "resourceType": "Observation",
      "id": "observation-11",
      "status": "final",
      "code": {
        "text": "Eye symptoms and examination"
      },
      "subject": {
        "reference": "Patient/patient-1"
      },
      "valueString": "Denies eye pain or visual change. No periorbital swelling or lid vesicles; conjunctiva clear and extraocular movements intact."
    },
    {
      "resourceType": "Observation",
      "id": "observation-12",
      "status": "final",
      "code": {
        "text": "Neurological symptoms and examination"
      },
      "subject": {
        "reference": "Patient/patient-1"
      },
      "valueString": "Denies facial weakness, confusion, neck stiffness, photophobia, or severe headache. Neurological examination grossly non-focal; GCS 15 and gait normal."
    },
    {
      "resourceType": "Observation",
      "id": "observation-13",
      "status": "final",
      "code": {
        "text": "Respiratory symptoms and chest examination"
      },
      "subject": {
        "reference": "Patient/patient-1"
      },
      "valueString": "Denies cough, shortness of breath, or pleuritic chest pain. Chest clear with good air entry."
    },
    {
      "resourceType": "Observation",
      "id": "observation-14",
      "status": "final",
      "code": {
        "text": "Gastrointestinal and oral symptoms and examination"
      },
      "subject": {
        "reference": "Patient/patient-1"
      },
      "valueString": "Denies current nausea or vomiting and abdominal pain; tolerating fluids, with decreased appetite but eating small meals. Abdomen soft and non-tender. Few small erythematous macules on the soft palate, without significant ulceration; swallowing is okay."
    },
    {
      "resourceType": "Observation",
      "id": "observation-15",
      "status": "final",
      "code": {
        "text": "Other reported symptoms"
      },
      "subject": {
        "reference": "Patient/patient-1"
      },
      "valueString": "Denies genitourinary symptoms or joint pains."
    },
    {
      "resourceType": "Observation",
      "id": "observation-16",
      "status": "final",
      "code": {
        "text": "General appearance and mental status"
      },
      "subject": {
        "reference": "Patient/patient-1"
      },
      "valueString": "Alert and oriented, mildly anxious, appears well hydrated and in no acute distress."
    },
    {
      "resourceType": "Observation",
      "id": "observation-17",
      "status": "final",
      "code": {
        "text": "Cardiovascular examination"
      },
      "subject": {
        "reference": "Patient/patient-1"
      },
      "valueString": "Heart sounds dual; no murmur."
    },
    {
      "resourceType": "Observation",
      "id": "observation-18",
      "status": "final",
      "code": {
        "text": "Anxiety"
      },
      "subject": {
        "reference": "Patient/patient-1"
      },
      "valueString": "Patient is very anxious after searching online for information about eczema herpeticum and chickenpox-related brain infection; mildly anxious on examination."
    }
  ]
}

